const D = { energy:.4, density:.6, hue:210, layersN:.6, twinkle:.6, direction:.25, nebulaA:.4, x:.5, y:.5, scale:1, speed:1, style:'deep', seed:0, alpha:95 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const dirA=P.direction*TAU;
const vx=Math.cos(dirA), vy=Math.sin(dirA);
function starHue(i){ if(sty==='warm') return 30+fr(i)*30; if(sty==='rainbow') return (i*57)%360; if(sty==='cyan') return 180+fr(i)*40; if(sty==='violet') return 260+fr(i)*50; return P.hue+fr(i)*40-20; }
// nebula wash drifting (motion + depth backdrop)
if(P.nebulaA>0.03){ dc.save(); blendMode(SCREEN);
 for(let i=0;i<3;i++){ const nx=W*(0.5+Math.sin(t*(0.05+i*0.023)+i*2)*0.4); const ny=H*(0.5+Math.cos(t*(0.04+i*0.017)+i)*0.35);
  const rg=dc.createRadialGradient(nx,ny,10,nx,ny,W*(0.25+i*0.1));
  rg.addColorStop(0,color((P.hue+i*40)%360,45,60,(6+3*Math.sin(t*0.3+i))*P.nebulaA*P.alpha/100).toString());
  rg.addColorStop(1,color((P.hue+i*40)%360,45,40,0).toString());
  dc.fillStyle=rg; dc.fillRect(0,0,W,H); }
 dc.restore(); blendMode(BLEND); }
// star layers (parallax drift)
const NL=2+Math.round(P.layersN*3);
dc.save(); blendMode(ADD);
for(let L=0;L<NL;L++){
  const depth=(L+1)/NL;
  const spd=(4+depth*26)*(0.4+en)*P.speed;
  const n=Math.floor((6+P.density*90)*(1.2-depth*0.5));
  for(let i=0;i<n;i++){
    const sx=((fr(i+L*97)*W + t*spd*vx)%W+W)%W;
    const sy=((fr(i+L*131)*H + t*spd*vy)%H+H)%H;
    const tw=P.twinkle>0.02? 0.5+0.5*Math.sin(t*(1+fr(i+L)*3)+i*2):1;
    const r=(0.6+depth*depth*3.2)*(0.6+P.scale*0.5)*(0.7+P.density*0.6+en*0.3);
    const h=starHue(i+L*7);
    if(depth>0.75 && tw>0.7){ dc.shadowBlur=6; dc.shadowColor=color(h,40,100).toString(); }
    fill(color(h, sty==='deep'?15:35, 100, (26+depth*55*tw)*P.alpha/100));
    circle(sx,sy,r*(0.7+tw*0.5));
    dc.shadowBlur=0;
    // near-layer streak hint
    if(depth>0.85){ stroke(color(h,25,100,(12*tw)*P.alpha/100)); strokeWeight(r*0.5); line(sx,sy, sx-vx*6, sy-vy*6); noStroke(); }
  }
}
dc.restore(); blendMode(BLEND);
